class Solution:
    def minOperations(self, s):
        n = len(s)
        a = [ord(c) - 97 for c in s]
        b = a + a
        best = float('inf')
        for r in range(n):
            cost = 0
            for i in range(n // 2):
                d = abs(b[r + i] - b[r + n - 1 - i])
                cost += d if d < 13 else 26 - d
            best = min(best, cost)
        return best

